/* ==========================================================================
   Masthead menu
   Which links sit in the bar and which move into the ☰ menu is decided in CSS
   (container query on the masthead, _sass/_custom.scss), so it never depends on
   measuring widths in JS and behaves the same under any page or browser zoom.
   This only opens/closes the ☰ menu and keeps the page clear of the fixed bar.
   ========================================================================== */
(function () {
  var nav = document.getElementById('site-nav');
  if (!nav) { return; }
  var btn = nav.querySelector('.greedy-nav__toggle');
  var menu = nav.querySelector('.hidden-links');

  var setOpen = function (open) {
    if (!btn || !menu) { return; }
    menu.classList.toggle('hidden', !open);
    btn.classList.toggle('close', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  };

  if (btn && menu) {
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      setOpen(menu.classList.contains('hidden'));
    });
    menu.addEventListener('click', function (e) { if (e.target.closest('a')) { setOpen(false); } });
    document.addEventListener('click', function (e) { if (!nav.contains(e.target)) { setOpen(false); } });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && !menu.classList.contains('hidden')) { setOpen(false); btn.focus(); }
    });
  }

  // Keep the content clear of the fixed masthead, whatever height it ends up at.
  var masthead = document.querySelector('.masthead');
  var pad = function () {
    if (!masthead) { return; }
    var h = masthead.offsetHeight;
    document.body.style.paddingTop = h + 'px';
    var sidebar = document.querySelector('.sidebar');
    var follow = document.querySelector('.author__urls-wrapper button');
    if (sidebar) { sidebar.style.paddingTop = (follow && follow.offsetParent !== null) ? '' : h + 'px'; }
  };
  pad();
  if ('ResizeObserver' in window && masthead) { new ResizeObserver(pad).observe(masthead); }
  window.addEventListener('resize', pad);
})();
/* ==========================================================================
   Various functions that we want to use within the template
   ========================================================================== */

/*jslint es6 */
'use strict';


// Detect OS/browser preference
const browserPref = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

// Determine the computed theme, which can be "dark" or "light".
function determineComputedTheme() {
  // Determine the expected state of the theme toggle, which can be "dark", "light", or default "system"
  let themeSetting = localStorage.getItem("theme");
  themeSetting = (themeSetting != "dark" && themeSetting != "light" && themeSetting != "system") ? "system" : themeSetting;

  // Return the setting if set, or use the browser preference
  if (themeSetting != "system") {
    return themeSetting;
  }
  return "light";   // professional default: light unless the visitor picks dark with the toggle
}

// Set the theme on page load or when explicitly called. Without an argument the
// theme is the stored preference or, failing that, the OS/browser preference.
function setTheme(theme) {
  const use_theme = theme || determineComputedTheme();

  if (use_theme === "dark") {
    $("html").attr("data-theme", "dark");
    $("#theme-icon").removeClass("fa-sun").addClass("fa-moon");
  } else if (use_theme === "light") {
    $("html").removeAttr("data-theme");
    $("#theme-icon").removeClass("fa-moon").addClass("fa-sun");
  }
}

// Toggle the theme manually
function toggleTheme() {
  const current_theme = $("html").attr("data-theme");
  const new_theme = current_theme === "dark" ? "light" : "dark";
  localStorage.setItem("theme", new_theme);
  setTheme(new_theme);
}


/* ==========================================================================
   Actions that should occur when the page has been fully loaded
   ========================================================================== */

$(document).ready(function () {
  // Kramdown supplies the permalink; move it after the heading when scripts run.
  document.querySelectorAll(":is(.page__content, .archive) :is(h1, h2, h3, h4, h5, h6)[id]").forEach(heading => {
    const link = heading.firstElementChild;
    if (link && link.matches("a[href^='#']:empty") && link.getAttribute("href") === "#" + heading.id) {
      link.classList.add("heading-permalink");
      link.setAttribute("aria-label", "Permalink");
      heading.appendChild(link);
    }
  });

  // SCSS SETTINGS - These should be the same as the settings in the relevant files
  const scssLarge = 925;          // pixels, from /_sass/_themes.scss
  const scssMastheadHeight = 70;  // pixels, from the current theme (e.g., /_sass/theme/_default.scss)

  // If the user hasn't chosen a theme, follow the OS preference
  setTheme();
  // (OS dark-mode changes are not followed automatically; the toggle controls the theme.)

  // Enable the theme toggle
  $('#theme-toggle').on('click', toggleTheme);

  // Footer placement is handled in CSS (_sass/_custom.scss); no JS needed.

  // Follow menu drop down
  $(".author__urls-wrapper button").on("click", function () {
    $(".author__urls").fadeToggle("fast", function () { });
    $(".author__urls-wrapper button").toggleClass("open");
  });

  // Restore the follow menu if toggled on a window resize
  jQuery(window).on('resize', function () {
    if ($('.author__urls.social-icons').css('display') == 'none' && $(window).width() >= scssLarge) {
      $(".author__urls").css('display', 'block')
    }
  });

});

/* ==========================================================================
   Single-page navigation: highlight the nav item for the section in view
   ========================================================================== */
(function () {
  const sections = document.querySelectorAll('.hx-section[id]');
  if (!sections.length || !('IntersectionObserver' in window)) { return; }

  const linksFor = function (id) {
    return document.querySelectorAll('#site-nav a[href$="#' + id + '"]');
  };
  const clear = function () {
    document.querySelectorAll('#site-nav li.selected').forEach(function (li) { li.classList.remove('selected'); });
  };

  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        clear();
        linksFor(entry.target.id).forEach(function (a) { a.parentElement.classList.add('selected'); });
      }
    });
  }, { rootMargin: '-40% 0px -55% 0px' });

  sections.forEach(function (s) { observer.observe(s); });

  // Back at the hero: nothing selected
  const hero = document.querySelector('.hx-hero');
  if (hero) {
    new IntersectionObserver(function (entries) {
      if (entries[0].isIntersecting && entries[0].intersectionRatio > 0.5) { clear(); }
    }, { threshold: [0.5] }).observe(hero);
  }
})();

/* ==========================================================================
   Single-page navigation: precise section jumps + the hidden shell
   - Short sections are centred in the visible area (below the fixed nav bar);
     tall sections start just under the nav bar.
   - The ghost icon reveals the hidden #shell section and glides down to it;
     `exit` (or the close button) hides it again and glides back up.
   - Works for clicks on this page and when arriving from another page (/#section).
   ========================================================================== */
(function () {
  const masthead = document.querySelector('.masthead');
  const shell = document.getElementById('shell');
  const ghost = document.querySelector('.hx-nav__ghost');
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const scrollToSection = function (el, smooth) {
    const head = masthead ? masthead.getBoundingClientRect().height : 0;
    const view = window.innerHeight - head;
    const rect = el.getBoundingClientRect();
    const top = rect.top + window.scrollY;
    let y = rect.height <= view - 40
      ? top - head - (view - rect.height) / 2     // fits: centre it
      : top - head - 16;                          // taller than the screen: align its top
    const maxY = document.documentElement.scrollHeight - window.innerHeight;
    y = Math.max(0, Math.min(y, maxY));
    window.scrollTo({ top: y, behavior: smooth && !reduceMotion ? 'smooth' : 'instant' });
  };

  const sectionFor = function (hash) {
    if (!hash || hash.length < 2) { return null; }
    let id; try { id = decodeURIComponent(hash.slice(1)); } catch (e) { return null; }   // malformed %-escapes
    const el = document.getElementById(id);
    return el && el.classList.contains('hx-section') ? el : null;
  };

  const openShell = function (smooth) {
    if (!shell) { return; }
    const wasHidden = shell.hidden;
    shell.hidden = false;
    if (wasHidden) {
      shell.classList.remove('is-open');
      void shell.offsetWidth;                    // restart the reveal animation
      shell.classList.add('is-open');
    }
    if (ghost) { ghost.classList.add('is-open'); ghost.setAttribute('aria-expanded', 'true'); }
    scrollToSection(shell, smooth);
    setTimeout(function () { document.dispatchEvent(new CustomEvent('hx-shell-open')); }, smooth && !reduceMotion ? 650 : 0);
  };

  const closeShell = function () {
    if (!shell || shell.hidden) { return; }
    if (ghost) { ghost.classList.remove('is-open'); ghost.setAttribute('aria-expanded', 'false'); }
    window.scrollTo({ top: 0, behavior: reduceMotion ? 'instant' : 'smooth' });
    setTimeout(function () { shell.hidden = true; shell.classList.remove('is-open'); }, reduceMotion ? 0 : 600);
    if (window.location.hash === '#shell') { history.pushState(null, '', window.location.pathname); }
  };

  // Mark the nav item for a section as active right away (the scroll-spy keeps it in sync afterwards)
  const markActive = function (id) {
    document.querySelectorAll('#site-nav li.selected').forEach(function (li) { li.classList.remove('selected'); });
    if (!id) { return; }
    document.querySelectorAll('#site-nav a[href$="#' + id + '"]').forEach(function (a) { a.parentElement.classList.add('selected'); });
  };

  const goTo = function (el, smooth) {
    markActive(el === shell ? null : el.id);
    if (el === shell) { openShell(smooth); } else { scrollToSection(el, smooth); }
  };

  const closeMobileMenu = function () {
    const hidden = document.querySelector('#site-nav .hidden-links');
    const btn = document.querySelector('#site-nav > .greedy-nav__toggle');
    if (hidden && !hidden.classList.contains('hidden')) {
      hidden.classList.add('hidden');
      if (btn) { btn.classList.remove('close'); }
    }
  };

  document.addEventListener('click', function (e) {
    if (e.target.closest('[data-shell-close]')) { e.preventDefault(); closeShell(); return; }
    const a = e.target.closest('a[href*="#"]');
    if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) { return; }
    if (a.origin !== window.location.origin || a.pathname !== window.location.pathname) { return; }
    const el = sectionFor(a.hash);
    if (!el) { return; }
    e.preventDefault();
    closeMobileMenu();
    if (el === shell && !shell.hidden && window.location.hash === '#shell') { closeShell(); return; }  // ghost toggles
    if (window.location.hash !== a.hash) { history.pushState(null, '', a.hash); }
    goTo(el, true);
  });

  document.addEventListener('hx-shell-close', closeShell);

  // Back/forward between sections
  window.addEventListener('popstate', function () {
    const el = sectionFor(window.location.hash);
    if (el) { goTo(el, true); } else if (shell && !shell.hidden) { closeShell(); }
  });

  // Arriving with /#section: position once everything has laid out
  const initial = sectionFor(window.location.hash);
  if (initial) {
    if ('scrollRestoration' in history) { history.scrollRestoration = 'manual'; }
    const settle = function () { setTimeout(function () { goTo(initial, false); }, 450); };
    if (document.readyState === 'complete') { settle(); } else { window.addEventListener('load', settle, { once: true }); }
  }
})();

/* ==========================================================================
   Hero name "decode" effect: characters resolve from random glyphs.
   Screen readers get the real name via aria-label; skipped for reduced motion.
   ========================================================================== */
(function () {
  const el = document.querySelector('[data-decode]');
  if (!el || window.matchMedia('(prefers-reduced-motion: reduce)').matches) { return; }
  const finalText = el.textContent.trim();
  if (!finalText) { return; }

  const glyphs = '!<>-_\\/[]{}=+*^?#$%&01░▒▓█';
  const rand = function () { return glyphs[Math.floor(Math.random() * glyphs.length)]; };
  const box = el.getBoundingClientRect();

  el.setAttribute('aria-label', finalText);
  el.style.minWidth = Math.ceil(box.width) + 'px';
  el.classList.add('is-decoding');
  const span = document.createElement('span');
  span.setAttribute('aria-hidden', 'true');
  el.textContent = '';
  el.appendChild(span);

  const duration = 1100;                 // ms until fully resolved
  const start = performance.now();
  const frame = function (now) {
    const progress = Math.min(1, (now - start) / duration);
    const revealed = Math.floor(progress * finalText.length);
    let out = '';
    for (let i = 0; i < finalText.length; i++) {
      const ch = finalText[i];
      out += (i < revealed || ch === ' ') ? ch : rand();
    }
    span.textContent = out;
    if (progress < 1) {
      requestAnimationFrame(frame);
    } else {
      el.textContent = finalText;
      el.removeAttribute('aria-label');
      el.classList.remove('is-decoding');
      el.style.minWidth = '';
    }
  };
  setTimeout(function () { requestAnimationFrame(frame); }, 250);
})();
